INSERT INTO dump_descriptions (base_key, description) VALUES ('bringbackfrozenenemyparticles', 'Restores frozen-enemy particles suppressed by particle-removal mods; load it above those mods in Mint.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('bringbackmineralfragments', 'Restores mineral and crystal mining fragments for players using particle-removal mods; load it above them in Mint.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
