INSERT INTO dump_descriptions (base_key, description) VALUES ('clientaxefix', 'Fixes client-side Driller axe bouncing; the host must install it. Axes still bounce off dwarves, drop pods and resupplies.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('clientaxefix_stickier', 'Host-required fix for client Driller axe bouncing, using the author’s stickier alternative.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('fmparticles', 'Restores the fear-triggering cloud burst after a successful Field Medic revive; load it above particle-removal mods.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('teparticles', 'Restores the Minigun T5B target-explosion particles; load it above particle-removal mods in Mint.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('v2_reduce_mining_fragments_minimal_dust__sparks', 'Cuts power-drill debris and reduces fragments from mining minerals and metals; Hollow Bough and Fungus Bogs are unchanged.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
