INSERT INTO dump_descriptions (base_key, description) VALUES ('sentriesondoretta', 'Places Engineer turrets on Doretta and makes them move with her. Host install is required for movement; recall before repositioning to avoid aim offsets.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
